<?php
namespace ExcelHerbal\ERP7\Organization;
use ExcelHerbal\ERP7\Security\DesignationDefaults;use ExcelHerbal\ERP7\Policy\CommercialPolicy;use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\BranchAuthority;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;use ExcelHerbal\ERP7\Security\HierarchyScope;
final class OrganizationProductService{
 public static function createProduct(Actor $a,array $data):array{Guard::cap($a,Capabilities::PRODUCT_MANAGE);$sku=strtoupper(trim((string)($data['sku']??'')));$name=trim((string)($data['name']??''));$uom=strtoupper(trim((string)($data['uom']??'PCS')))?:'PCS';$mode=strtolower(trim((string)($data['batch_tracking']??'optional')));$expiry=!empty($data['expiry_tracking']);if($sku===''||$name===''||!in_array($mode,['off','optional','required'],true))throw new DomainException('Valid SKU, name and batch mode are required.');if($expiry&&$mode==='off')throw new DomainException('Expiry tracking requires batch tracking.','product_expiry_batch_required',422);if(strlen($sku)>80||strlen($name)>190||strlen($uom)>40)throw new DomainException('Product SKU, name or UOM is too long.','product_fields_invalid',422);return Transaction::run(function()use($a,$data,$sku,$name,$uom,$mode,$expiry){$db=Db::wpdb();Db::mustInsert($db,Db::table('products'),['company_id'=>$a->companyId,'sku'=>$sku,'name'=>$name,'uom'=>$uom,'batch_tracking'=>$mode,'expiry_tracking'=>$expiry?1:0,'status'=>'active','created_at'=>Db::now()],'Product SKU already exists.','product_duplicate');$id=(int)$db->insert_id;self::commercialRevision($a,$id,$data,'Initial commercial values');Audit::add($a,'product.create','product',$id,['sku'=>$sku]);return['id'=>$id,'sku'=>$sku,'status'=>'active'];});}
 public static function commercialRevision(Actor $a,int $productId,array $data,string $reason=''):array{Guard::cap($a,Capabilities::PRODUCT_MANAGE);$db=Db::wpdb();$p=$db->get_row($db->prepare("SELECT id FROM ".Db::table('products')." WHERE id=%d AND company_id=%d AND status='active'",$productId,$a->companyId),ARRAY_A);if(!$p)throw new DomainException('Active product not found.','product_not_found',404);$values=CommercialPolicy::values($data);$effectiveRaw=trim((string)($data['effective_from']??''));$effective=$effectiveRaw===''?Db::now():Input::optionalUtcDateTime($effectiveRaw,'Commercial effective_from');$why=trim($reason?:((string)($data['reason']??'')));if(strlen($why)>255)throw new DomainException('Commercial revision reason is too long.','commercial_reason_invalid',422);Db::mustInsert($db,Db::table('product_commercial_revisions'),['company_id'=>$a->companyId,'product_id'=>$productId,'effective_from'=>$effective]+$values+['reason'=>$why?:null,'status'=>'active','approved_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'product.commercial_revision','product',$productId,['revision_id'=>$id,'effective_from'=>$effective,'reason'=>$why]);return['id'=>$id,'product_id'=>$productId,'effective_from'=>$effective];}
 public static function commercialHistory(Actor $a,int $productId):array{Guard::cap($a,Capabilities::PRODUCT_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('product_commercial_revisions')." WHERE company_id=%d AND product_id=%d ORDER BY effective_from DESC,id DESC",$a->companyId,$productId),ARRAY_A);}
 public static function updateProduct(Actor $a,int $productId,array $data):array{
  Guard::cap($a,Capabilities::PRODUCT_MANAGE);$db=Db::wpdb();$t=Db::table('products');$p=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d",$productId,$a->companyId),ARRAY_A);if(!$p)throw new DomainException('Product not found.','product_not_found',404);$chg=[];if(array_key_exists('name',$data)){$v=trim((string)$data['name']);if($v===''||strlen($v)>190)throw new DomainException('Valid product name is required.','product_fields_invalid',422);$chg['name']=$v;}if(array_key_exists('sku',$data)){$v=strtoupper(trim((string)$data['sku']));if($v===''||strlen($v)>80)throw new DomainException('Valid product SKU is required.','product_fields_invalid',422);$exists=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND sku=%s AND id<>%d",$a->companyId,$v,$productId));if($exists)throw new DomainException('Product SKU already exists.','product_duplicate',409);$chg['sku']=$v;}
  $struct=array_intersect(array_keys($data),['uom','batch_tracking','expiry_tracking']);if($struct){$moves=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_ledger')." WHERE company_id=%d AND product_id=%d",$a->companyId,$productId));if($moves)throw new DomainException('UOM/batch settings cannot change after stock movement.','product_structure_locked',409);if(array_key_exists('uom',$data)){$v=strtoupper(trim((string)$data['uom']));if($v===''||strlen($v)>40)throw new DomainException('Valid UOM is required.','product_fields_invalid',422);$chg['uom']=$v;}if(array_key_exists('batch_tracking',$data)){$v=strtolower(trim((string)$data['batch_tracking']));if(!in_array($v,['off','optional','required'],true))throw new DomainException('Invalid batch tracking mode.','product_fields_invalid',422);$chg['batch_tracking']=$v;}if(array_key_exists('expiry_tracking',$data))$chg['expiry_tracking']=!empty($data['expiry_tracking'])?1:0;$nextMode=(string)($chg['batch_tracking']??$p['batch_tracking']);$nextExpiry=(int)($chg['expiry_tracking']??$p['expiry_tracking']);if($nextExpiry===1&&$nextMode==='off')throw new DomainException('Expiry tracking requires batch tracking.','product_expiry_batch_required',422);}
  if(!$chg)throw new DomainException('No editable product fields supplied.','parameter_required',422);Db::mustUpdate($db,$t,$chg,['id'=>$productId,'company_id'=>$a->companyId]);Audit::add($a,'product.update','product',$productId,['fields'=>array_keys($chg)]);return['id'=>$productId]+$chg+['status'=>(string)$p['status']];
 }
 public static function setProductStatus(Actor $a,int $productId,bool $active):array{
  Guard::cap($a,Capabilities::PRODUCT_MANAGE);return Transaction::run(function()use($a,$productId,$active){
   $db=Db::wpdb();$t=Db::table('products');$p=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$productId,$a->companyId),ARRAY_A);if(!$p)throw new DomainException('Product not found.','product_not_found',404);$target=$active?'active':'inactive';
   if(!$active){
    $qty=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(quantity),0) FROM ".Db::table('stock_balances')." WHERE company_id=%d AND product_id=%d AND quantity>0",$a->companyId,$productId));if($qty>.0001)throw new DomainException('Product still has positive stock.','product_deactivate_blocked',409);
    $openTransfer=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_transfer_lines')." l JOIN ".Db::table('stock_transfers')." h ON h.id=l.transfer_id WHERE h.company_id=%d AND l.product_id=%d AND h.status NOT IN ('received','cancelled')",$a->companyId,$productId));if($openTransfer)throw new DomainException('Product is referenced by an open stock transfer.','product_deactivate_blocked',409);
    $pendingAdjustment=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_adjustment_lines')." l JOIN ".Db::table('stock_adjustments')." h ON h.id=l.adjustment_id WHERE h.company_id=%d AND l.product_id=%d AND h.status='pending'",$a->companyId,$productId));if($pendingAdjustment)throw new DomainException('Product is referenced by a pending stock adjustment.','product_deactivate_blocked',409);
    $openDaily=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_request_lines')." l JOIN ".Db::table('daily_requests')." r ON r.id=l.daily_request_id JOIN ".Db::table('daily_cycles')." c ON c.id=r.daily_cycle_id WHERE c.company_id=%d AND l.product_id=%d AND r.status IN ('draft','submitted','approved')",$a->companyId,$productId));if($openDaily)throw new DomainException('Product is referenced by an open Daily Order request.','product_deactivate_blocked',409);
    $quarantine=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_quarantine')." WHERE company_id=%d AND product_id=%d AND status='open'",$a->companyId,$productId));if($quarantine)throw new DomainException('Product has unresolved quarantined stock.','product_deactivate_blocked',409);
   }else{
    $commercial=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('product_commercial_revisions')." WHERE company_id=%d AND product_id=%d AND status='active'",$a->companyId,$productId));if(!$commercial)throw new DomainException('Product cannot be activated without an active commercial revision.','commercial_missing',409);
   }
   Db::mustUpdate($db,$t,['status'=>$target],['id'=>$productId,'company_id'=>$a->companyId]);Audit::add($a,'product.status','product',$productId,['status'=>$target]);return['id'=>$productId,'status'=>$target];
  });
 }

}
